/**
 * Module-specific consignes and student responses for CFA exercises.
 * Maps RNCP competence titles to realistic, detailed exercise content.
 */

/** Module-specific consignes mapped by competence keyword */
export function getModuleSpecificConsigne(matiereTitle: string, matiereContenu: string, moduleTitle: string, si: number, exerciceIdx: number, hash: number): string {
  const mt = (matiereTitle || '').toLowerCase();

  // NTC - Bloc 1: Prospection
  if (mt.includes('veille commerciale') || (mt.includes('veille') && !mt.includes('information'))) {
    const consignes = [
      `L'entreprise TechSolutions SAS souhaite lancer un nouveau produit connecté sur le marché B2B. Votre responsable vous demande de réaliser une veille commerciale complète sur ce secteur.\n\n1. Identifiez 5 sources de veille pertinentes (sites, salons, réseaux sociaux professionnels, newsletters spécialisées) et justifiez chaque choix.\n2. Réalisez une analyse concurrentielle de 3 acteurs majeurs du marché en utilisant une matrice SWOT.\n3. Identifiez les tendances du marché et les évolutions réglementaires qui pourraient impacter le lancement.\n4. Proposez un tableau de bord de veille avec les indicateurs clés à surveiller mensuellement.\n\nVotre livrable doit être structuré, argumenté et directement exploitable par la direction commerciale.`,
      `Vous travaillez au sein du service commercial de l'entreprise GreenEnergy SARL spécialisée dans les solutions photovoltaïques pour les professionnels. Votre directeur commercial vous confie la mission suivante :\n\n1. Mettez en place un système de veille concurrentielle : identifiez les 4 principaux concurrents, analysez leur positionnement prix, leurs offres et leur communication.\n2. Réalisez un benchmark des pratiques commerciales du secteur (méthodes de prospection, canaux utilisés, argumentaires).\n3. Analysez les évolutions réglementaires récentes (aides de l'État, normes) et leur impact sur votre activité.\n4. Rédigez une note de synthèse de 2 pages à destination de votre direction avec vos recommandations.\n\nDocuments attendus : tableau comparatif concurrentiel + note de synthèse.`,
    ];
    return consignes[(hash + exerciceIdx) % consignes.length];
  }

  if (mt.includes('plan d\'actions commerciales') || mt.includes('plan d\'action')) {
    const consignes = [
      `L'entreprise IndustriePro SA vous confie le développement d'un nouveau secteur géographique (Région Occitanie). Le portefeuille actuel compte 45 clients pour un CA de 380 000€. L'objectif N+1 est d'atteindre 520 000€.\n\n1. Définissez 4 objectifs SMART pour ce développement commercial.\n2. Élaborez un plan d'actions commerciales sur 6 mois avec un rétroplanning détaillé (actions, cibles, moyens, échéances).\n3. Proposez un budget prévisionnel pour chaque action (prospection terrain, emailing, salons, social selling).\n4. Concevez un tableau de bord CRM avec les KPIs à suivre (nombre de RDV, taux de transformation, CA généré, pipe commercial).\n5. Prévoyez un plan B en cas de résultats inférieurs aux prévisions à mi-parcours.\n\nLivrable attendu : plan d'actions commerciales complet prêt à être présenté en réunion commerciale.`,
      `Vous êtes technico-commercial chez DigiPrint Solutions, spécialisée dans les solutions d'impression professionnelle. Votre responsable vous demande d'organiser le lancement commercial d'une nouvelle gamme éco-responsable.\n\n1. Analysez le potentiel du marché : identifiez 3 segments cibles et créez un persona pour chacun.\n2. Rédigez un plan d'actions commerciales trimestriel avec : objectifs chiffrés, actions prioritaires, canaux de communication, budget estimé.\n3. Planifiez une campagne de prospection multicanale (emailing + phoning + LinkedIn) avec un calendrier précis.\n4. Créez un argumentaire commercial adapté à chaque segment.\n5. Définissez les indicateurs de suivi et le format de reporting hebdomadaire.\n\nPrésentez votre plan sous forme de document structuré avec tableaux et rétroplanning.`,
    ];
    return consignes[(hash + exerciceIdx) % consignes.length];
  }

  if (mt.includes('prospecter') || mt.includes('prospection')) {
    const consignes = [
      `Vous êtes en charge de la prospection d'un nouveau secteur pour l'entreprise MécaPrécision. Votre objectif : obtenir 12 rendez-vous qualifiés en 4 semaines auprès de PME industrielles.\n\n1. Constituez un fichier de prospection de 50 entreprises cibles en utilisant les critères de segmentation vus en cours (secteur, taille, CA, localisation). Justifiez vos choix.\n2. Rédigez un script de phoning de prise de RDV avec : accroche, questionnement de découverte, traitement de 3 objections courantes, conclusion.\n3. Rédigez un email de prospection initial + un email de relance à J+5.\n4. Préparez un message d'approche LinkedIn personnalisé.\n5. Établissez un planning de prospection sur 4 semaines avec les créneaux horaires et les objectifs quotidiens.\n\nChaque livrable doit être directement utilisable en situation professionnelle.`,
      `L'entreprise AquaFilt Pro vous mandate pour prospecter le marché des collectivités locales pour ses systèmes de filtration d'eau. Budget : néant (prospection directe uniquement).\n\n1. Identifiez 30 collectivités cibles en Région Sud en justifiant vos critères de sélection.\n2. Créez 2 personas distincts (décideur technique vs décideur administratif).\n3. Rédigez un argumentaire de vente adapté à chaque persona.\n4. Préparez un pitch téléphonique de 2 minutes maximum.\n5. Simulez une séquence de prospection complète : email d'introduction → relance téléphonique → message LinkedIn → email de suivi.\n6. Proposez un système de scoring des prospects (chaud/tiède/froid) avec les critères de qualification.\n\nPrésentez l'ensemble sous forme de dossier de prospection structuré.`,
    ];
    return consignes[(hash + exerciceIdx) % consignes.length];
  }

  if (mt.includes('performance') || mt.includes('analyser ses performances')) {
    const consignes = [
      `Voici les résultats commerciaux du trimestre T3 de l'équipe commerciale Sud-Est :\n- Objectif CA : 250 000€ / Réalisé : 187 000€ (75%)\n- RDV planifiés : 80 / RDV réalisés : 52 / Devis envoyés : 38 / Commandes signées : 15\n- Taux de transformation global : 18,75% (objectif : 25%)\n- Panier moyen : 12 467€ (objectif : 15 000€)\n- 3 clients perdus sur le trimestre\n\n1. Analysez ces résultats en calculant les écarts par rapport aux objectifs. Identifiez les points forts et les points faibles.\n2. Formulez des hypothèses sur les causes des écarts constatés.\n3. Proposez un plan d'actions correctives chiffré pour le T4 avec des actions concrètes pour chaque indicateur défaillant.\n4. Rédigez un reporting synthétique d'une page pour la direction commerciale.\n5. Définissez les nouveaux objectifs T4 en les justifiant.\n\nUtilisez des tableaux et graphiques pour appuyer votre analyse.`,
      `En tant que technico-commercial chez BâtiRénov, vous devez analyser vos performances individuelles du semestre.\n\nDonnées fournies :\n- Portefeuille : 62 clients actifs / 15 prospects en cours\n- CA réalisé : 142 000€ sur objectif de 180 000€\n- 8 nouveaux clients acquis (objectif : 12)\n- Taux de fidélisation : 88% (objectif : 95%)\n- Délai moyen de closing : 45 jours (objectif : 30 jours)\n- Marge moyenne : 22% (objectif : 28%)\n\n1. Calculez l'ensemble des KPIs et identifiez les 3 indicateurs les plus critiques.\n2. Analysez les causes racines des contre-performances identifiées.\n3. Élaborez un plan d'actions personnel sur 3 mois avec des objectifs hebdomadaires.\n4. Proposez des outils de suivi (tableau de bord personnel, alertes CRM).\n5. Rédigez un auto-bilan argumenté de votre activité commerciale.`,
    ];
    return consignes[(hash + exerciceIdx) % consignes.length];
  }

  // NTC - Bloc 2: Négociation
  if (mt.includes('représenter l\'entreprise') || mt.includes('valoriser son image') || mt.includes('représenter')) {
    const consignes = [
      `Votre entreprise LogiTrans participe au salon professionnel Transport & Logistique 2025 à Lyon. Vous êtes en charge de la représentation commerciale sur le stand.\n\n1. Préparez un elevator pitch de 90 secondes présentant l'entreprise et ses solutions.\n2. Rédigez un argumentaire valorisant l'image de marque (historique, certifications, références clients, valeurs).\n3. Préparez 5 questions d'accroche pour engager la conversation avec les visiteurs du salon.\n4. Concevez un plan de suivi post-salon : qualification des contacts, emails personnalisés, relance téléphonique.\n5. Rédigez un compte-rendu type de visite de stand avec les informations à collecter.\n\nL'ensemble doit être cohérent avec le positionnement premium de l'entreprise.`,
      `Vous représentez l'entreprise CyberShield lors d'un événement networking organisé par la CCI. L'objectif est de nouer des contacts commerciaux dans le secteur des PME.\n\n1. Rédigez votre présentation personnelle professionnelle (qui vous êtes, ce que fait votre entreprise, votre valeur ajoutée).\n2. Préparez 3 posts LinkedIn (avant, pendant, après l'événement) pour valoriser votre participation.\n3. Créez une fiche entreprise synthétique à distribuer aux contacts (format A5).\n4. Élaborez un système de qualification des contacts rencontrés (critères, scoring).\n5. Proposez un plan d'action de suivi dans les 48h post-événement.\n\nMontrez comment vous incarnez les valeurs et l'expertise de votre entreprise.`,
    ];
    return consignes[(hash + exerciceIdx) % consignes.length];
  }

  if (mt.includes('proposition technique') || mt.includes('concevoir une proposition')) {
    const consignes = [
      `Le client MétalFrance (PME de 85 salariés, CA 12M€, secteur métallurgie) souhaite moderniser son parc informatique et recherche une solution de gestion intégrée (ERP). Budget annoncé : 45 000€ à 60 000€.\n\nAprès un rendez-vous de découverte, vous avez identifié les besoins suivants :\n- Gestion des stocks en temps réel\n- Suivi de production avec traçabilité\n- Module de facturation et comptabilité\n- Accès mobile pour les commerciaux terrain\n\n1. Rédigez une proposition technique détaillée avec l'architecture de la solution.\n2. Élaborez un chiffrage complet (licences, installation, formation, maintenance) avec 2 options.\n3. Construisez un argumentaire ROI pour justifier l'investissement.\n4. Préparez un planning de déploiement réaliste.\n5. Anticipez 3 objections probables du client et préparez vos réponses.\n\nLa proposition doit être professionnelle et prête à être envoyée au client.`,
      `L'entreprise BioDistrib (grossiste bio, 120 salariés, 25 points de vente) vous sollicite pour une solution de traçabilité logistique.\n\nBesoins identifiés :\n- Suivi des lots de la réception à la livraison\n- Gestion des DLC/DDM\n- Interface avec les transporteurs\n- Reporting réglementaire\n\n1. Analysez les besoins et reformulez-les en spécifications techniques.\n2. Proposez 2 solutions (standard vs sur-mesure) avec un comparatif avantages/inconvénients.\n3. Rédigez un chiffrage détaillé pour chaque option.\n4. Calculez le TCO (Total Cost of Ownership) sur 3 ans.\n5. Préparez une présentation de 10 slides pour le comité de direction.\n\nVotre proposition doit démontrer votre expertise technique et commerciale.`,
    ];
    return consignes[(hash + exerciceIdx) % consignes.length];
  }

  if (mt.includes('négocier') || mt.includes('négociation')) {
    const consignes = [
      `Mise en situation : Vous êtes en rendez-vous de négociation finale avec M. Durand, directeur des achats de l'entreprise PlastiPack (250 salariés). Votre proposition porte sur un contrat de maintenance industrielle d'une valeur de 78 000€/an sur 3 ans.\n\nLe client a formulé les objections suivantes :\n- « Votre prix est 15% plus élevé que votre concurrent principal »\n- « Nous souhaitons une période d'essai de 6 mois avant engagement »\n- « Nous voulons une clause de sortie à tout moment »\n- « Le délai d'intervention de 4h ne nous convient pas, nous voulons 2h »\n\n1. Préparez votre stratégie de négociation : quelles concessions êtes-vous prêt à faire ? Quelles sont vos lignes rouges ?\n2. Rédigez votre argumentaire pour chaque objection avec la méthode CRAC.\n3. Proposez une contre-offre structurée qui préserve votre marge (minimum 25%).\n4. Simulez le déroulé de la négociation en rédigeant le dialogue.\n5. Rédigez le compte-rendu de négociation et la proposition révisée.`,
      `Contexte : Vous négociez le renouvellement d'un contrat annuel avec votre client historique FoodExpress (restauration collective). Le contrat actuel : 52 000€/an. Le client menace de partir chez un concurrent qui propose 42 000€/an.\n\nInformations supplémentaires :\n- Client depuis 5 ans, jamais eu de litige\n- Votre coût de revient : 35 000€\n- Le concurrent propose un service avec des délais de livraison plus longs\n- Le client est en croissance (+3 nouveaux sites prévus)\n\n1. Analysez la situation : rapport de force, enjeux pour chaque partie, BATNA de chacun.\n2. Préparez votre matrice de négociation (points négociables, contreparties attendues, zone d'accord possible).\n3. Rédigez votre argumentaire de fidélisation avec calcul du coût de changement pour le client.\n4. Proposez une offre de renouvellement créative intégrant les nouveaux sites.\n5. Rédigez l'email de synthèse post-négociation confirmant les accords.`,
    ];
    return consignes[(hash + exerciceIdx) % consignes.length];
  }

  if (mt.includes('bilan') || mt.includes('ajuster son activité')) {
    return `Fin d'année commerciale : vous devez réaliser le bilan complet de votre activité et le présenter à votre direction.\n\nDonnées de l'année :\n- CA réalisé : 425 000€ (objectif : 480 000€) soit 88,5%\n- 18 nouveaux clients (objectif : 25)\n- Taux de transformation des devis : 32% (objectif : 40%)\n- Taux de satisfaction client : 4,2/5\n- 2 clients perdus (CA perdu : 35 000€)\n- Marge moyenne : 31%\n\n1. Rédigez un bilan d'activité annuel structuré (contexte, résultats, analyse des écarts).\n2. Identifiez les 3 principaux facteurs de succès et les 3 principaux freins.\n3. Formulez des recommandations argumentées pour l'année N+1.\n4. Proposez des objectifs révisés réalistes avec un plan d'action trimestriel.\n5. Préparez un support de présentation synthétique (plan de 8 slides).\n\nVotre bilan doit être factuel, honnête et orienté solutions.`;
  }

  if (mt.includes('relation client') || mt.includes('fidélisation') || mt.includes('gestion de la relation')) {
    const consignes = [
      `Votre portefeuille clients chez TechnoServ comprend 75 comptes actifs. Votre direction vous demande de mettre en place une stratégie de fidélisation pour réduire le taux d'attrition (actuellement 12%, objectif 5%).\n\n1. Segmentez votre portefeuille clients (A/B/C) selon des critères pertinents (CA, potentiel, ancienneté, marge). Présentez votre matrice de segmentation.\n2. Définissez un plan de fidélisation adapté à chaque segment (fréquence de contact, actions commerciales, avantages).\n3. Rédigez un processus de gestion des réclamations en 5 étapes.\n4. Proposez une stratégie d'upselling/cross-selling avec 3 scénarios concrets.\n5. Créez un questionnaire de satisfaction client (10 questions) et décrivez le plan d'exploitation des résultats.\n6. Mettez en place un système d'alerte CRM pour détecter les signaux de désengagement.\n\nJustifiez chaque choix par des données chiffrées ou des arguments commerciaux.`,
      `Client mécontent : la société TransLogis vous appelle car sa dernière commande (15 000€) a été livrée avec 8 jours de retard et 2 produits non conformes. Le client menace de résilier son contrat (CA annuel : 85 000€).\n\n1. Rédigez le script de l'appel de gestion de crise : écoute, reconnaissance, solution immédiate.\n2. Proposez un plan de résolution concret avec un calendrier.\n3. Rédigez un email de suivi post-appel professionnel.\n4. Élaborez un geste commercial justifié et proportionné.\n5. Mettez en place un plan de reconquête sur 3 mois.\n6. Proposez des mesures correctives internes pour éviter que le problème ne se reproduise.\n\nMontrez votre capacité à transformer un problème en opportunité de fidélisation.`,
    ];
    return consignes[(hash + exerciceIdx) % consignes.length];
  }

  // Assistant de direction
  if (mt.includes('organiser et coordonner') || mt.includes('gestion d\'agenda') || mt.includes('organisation de réunions')) {
    return `Votre directeur, M. Bernard, vous demande d'organiser le séminaire annuel de l'entreprise (35 participants, 2 jours, budget 12 000€).\n\n1. Proposez 3 lieux adaptés avec un comparatif (capacité, services, prix, accessibilité).\n2. Élaborez un programme détaillé sur 2 jours (plénières, ateliers, pauses, repas, activité team-building).\n3. Rédigez l'invitation officielle aux participants avec toutes les informations logistiques.\n4. Créez un rétroplanning d'organisation (J-60 à J+7).\n5. Préparez un budget prévisionnel détaillé poste par poste.\n6. Listez tous les documents et supports à préparer.\n\nL'ensemble doit être prêt à être validé par la direction.`;
  }

  if (mt.includes('outils de pilotage') || mt.includes('tableaux de bord') || mt.includes('indicateurs')) {
    return `La direction vous demande de créer un tableau de bord de suivi d'activité pour le comité de direction mensuel.\n\nDonnées à intégrer :\n- CA mensuel vs objectif (par service)\n- Effectifs et taux d'absentéisme\n- Satisfaction client (NPS)\n- Projets en cours (avancement, budget, délais)\n- Indicateurs RH (recrutements, formations, turnover)\n\n1. Concevez la maquette du tableau de bord sur une page A4 (disposition, graphiques, code couleur).\n2. Définissez les sources de données et la fréquence de mise à jour pour chaque indicateur.\n3. Proposez un système d'alertes visuelles (vert/orange/rouge) avec les seuils.\n4. Rédigez une procédure de collecte des données auprès des services.\n5. Préparez un modèle de note de synthèse accompagnant le tableau de bord.\n\nLe tableau de bord doit être clair, synthétique et exploitable en réunion.`;
  }

  if (mt.includes('processus administratifs') || mt.includes('dématérialisation') || mt.includes('archivage') || mt.includes('optimiser les processus')) {
    return `L'entreprise passe au zéro papier. Votre mission : piloter la dématérialisation du service administratif.\n\n1. Réalisez un audit des processus actuels : listez les 10 documents papier les plus fréquents, leur volume mensuel et leur circuit de validation.\n2. Proposez une solution de GED (Gestion Électronique de Documents) : critères de choix, comparatif de 3 solutions, recommandation argumentée.\n3. Rédigez la nouvelle procédure de classement et d'archivage numérique (arborescence, nomenclature, droits d'accès).\n4. Élaborez un plan de migration sur 6 mois avec les étapes clés.\n5. Préparez un guide utilisateur synthétique pour les collaborateurs.\n6. Définissez les indicateurs de réussite du projet.\n\nVotre proposition doit être réaliste et tenir compte des résistances au changement.`;
  }

  if (mt.includes('synthèse') || mt.includes('recherche') || mt.includes('diffusion de l\'information')) {
    return `Votre directeur doit intervenir dans une conférence sur la transformation digitale des PME. Il vous demande de préparer un dossier de synthèse complet.\n\n1. Identifiez 8 sources fiables et variées (études, rapports, articles, statistiques officielles).\n2. Rédigez une note de synthèse de 3 pages structurée : contexte, enjeux, tendances, chiffres clés, recommandations.\n3. Préparez 5 fiches thématiques d'une demi-page chacune (IA, cloud, cybersécurité, télétravail, e-commerce).\n4. Sélectionnez et commentez 3 graphiques/infographies pertinents.\n5. Rédigez les éléments de langage pour l'intervention orale (messages clés, chiffres à retenir).\n\nLe dossier doit être sourcé, objectif et directement exploitable.`;
  }

  if (mt.includes('communication écrite') || mt.includes('anglais') || mt.includes('rédaction') || mt.includes('correspondance')) {
    return `Exercice de rédaction professionnelle bilingue :\n\n1. Rédigez en français un compte-rendu de réunion de direction (ordre du jour : lancement produit, budget Q3, recrutements) à partir des notes suivantes : « pduit lancmt 15/10 – budget 85k validé – 2 recrut CDI prévus – pvision CA +12% – point juridique en cours »\n2. Traduisez les points clés en anglais pour les partenaires internationaux.\n3. Rédigez un email en anglais à un fournisseur britannique pour négocier un délai de paiement (passage de 30 à 60 jours).\n4. Préparez en français une note interne annonçant un changement d'organisation (fusion de 2 services).\n5. Corrigez et améliorez le courrier suivant : « Monsieur, suite a notre conversation téléphonique je vous envoi les documents demander. Merci de bien vouloir les signer et nous les retourner dans les plus bref delais. »\n\nSoignez le registre de langue, la mise en forme et les formules professionnelles.`;
  }

  if (mt.includes('interface') || mt.includes('accueil') || mt.includes('communication interpersonnelle') || mt.includes('partenaires')) {
    return `Vous êtes assistant(e) de direction. Plusieurs situations se présentent dans la même journée :\n\nSituation 1 : Un client important arrive avec 30 minutes d'avance. Le directeur est en réunion. Que faites-vous ? Rédigez le dialogue.\n\nSituation 2 : Un fournisseur appelle mécontent car sa facture n'est pas réglée depuis 45 jours. Le comptable est absent. Rédigez le script téléphonique.\n\nSituation 3 : Deux collaborateurs sont en conflit ouvert. L'un vient vous voir pour se plaindre de l'autre. Comment gérez-vous la situation ?\n\nSituation 4 : Votre directeur vous demande de refuser poliment une demande de rendez-vous d'un commercial insistant. Rédigez l'email de refus diplomatique.\n\nPour chaque situation :\n1. Décrivez votre démarche étape par étape.\n2. Rédigez les échanges (dialogues ou écrits).\n3. Justifiez vos choix en vous appuyant sur les techniques de communication vues en cours.`;
  }

  // Développeur web
  if (mt.includes('html') || mt.includes('css') || mt.includes('intégration web') || mt.includes('maquette')) {
    return `Vous devez intégrer la maquette d'une page d'accueil pour une agence de voyage en ligne.\n\nSpécifications :\n- Header : logo, menu de navigation (5 items), barre de recherche\n- Section hero : image de fond, titre accrocheur, formulaire de recherche (destination, dates, voyageurs)\n- Section « Destinations populaires » : grille de 6 cartes avec image, titre, prix, bouton\n- Section témoignages : carrousel de 3 avis clients\n- Footer : liens utiles, réseaux sociaux, newsletter\n\n1. Écrivez le code HTML sémantique complet (utilisation appropriée des balises section, article, nav, header, footer).\n2. Créez la feuille de style CSS avec une approche mobile-first.\n3. Rendez la page responsive (breakpoints : 768px, 1024px, 1200px).\n4. Ajoutez des transitions CSS sur les cartes (hover) et le menu.\n5. Validez l'accessibilité : attributs alt, contrastes, navigation clavier.\n\nLe code doit être propre, commenté et respecter les bonnes pratiques.`;
  }

  if (mt.includes('javascript') || mt.includes('dynamique') || mt.includes('interactivité')) {
    return `Développez une application de gestion de tâches (To-Do List) en JavaScript vanilla.\n\nFonctionnalités demandées :\n- Ajouter une tâche (titre, description, priorité haute/moyenne/basse, date limite)\n- Marquer une tâche comme terminée\n- Supprimer une tâche avec confirmation\n- Filtrer par statut (toutes, actives, terminées) et par priorité\n- Trier par date limite ou par priorité\n- Persistence des données en localStorage\n- Compteur de tâches restantes\n\n1. Écrivez le code JavaScript en utilisant les concepts vus en cours (DOM, événements, localStorage, classes ES6).\n2. Structurez votre code en modules/classes.\n3. Gérez les cas d'erreur (champ vide, date passée).\n4. Ajoutez des animations CSS pour l'ajout/suppression de tâches.\n5. Commentez votre code et expliquez vos choix techniques.\n\nLe code doit fonctionner sans framework externe.`;
  }

  if (mt.includes('react') || mt.includes('framework') || mt.includes('composant')) {
    return `Créez une application React de gestion de contacts professionnels.\n\nFonctionnalités :\n- Formulaire d'ajout/modification de contact (nom, prénom, email, téléphone, entreprise, poste)\n- Liste des contacts avec recherche en temps réel\n- Fiche détaillée d'un contact\n- Système de favoris\n- Catégorisation (client, prospect, fournisseur, partenaire)\n\n1. Décomposez l'application en composants React réutilisables.\n2. Gérez l'état avec useState/useReducer.\n3. Implémentez le routing avec React Router.\n4. Validez les formulaires (email valide, champs requis).\n5. Gérez la persistence avec localStorage.\n6. Écrivez au moins 3 tests unitaires.\n\nJustifiez vos choix d'architecture.`;
  }

  if (mt.includes('base de données') || mt.includes('sql') || mt.includes('back-end') || mt.includes('api') || mt.includes('serveur')) {
    return `Concevez et implémentez la partie back-end d'une application de réservation de salles de réunion.\n\nModèle de données :\n- Utilisateurs (id, nom, email, service)\n- Salles (id, nom, capacité, équipements, étage)\n- Réservations (id, salle_id, user_id, date, heure_début, heure_fin, objet)\n\n1. Créez le schéma de base de données avec les relations (MCD puis MLD).\n2. Écrivez les requêtes SQL de création des tables avec contraintes.\n3. Rédigez 10 requêtes SQL : INSERT, SELECT (avec jointures), UPDATE, DELETE, requêtes agrégées.\n4. Créez une API REST avec les endpoints CRUD pour chaque entité.\n5. Implémentez la logique de vérification des conflits de réservation.\n\nDocumentez votre API (endpoints, méthodes, paramètres, réponses).`;
  }

  // ===== VTC (RS5637) =====
  if (mt.includes('vtc') || mt.includes('réglementation t3p') || mt.includes('t3p') || mt.includes('transport public particulier')) {
    const consignes = [
      `Examen blanc — Réglementation T3P (épreuve commune VTC)\n\nVous candidatez à l'examen VTC organisé par la CMA. Préparez les questions suivantes en argumentant chaque réponse :\n\n1. Quelles sont les 4 différences fondamentales entre l'activité de Taxi et celle de VTC (maraude, tarification, signalétique, retour à la base) ?\n2. Quels sont les 3 documents obligatoires à présenter en cas de contrôle (carte professionnelle, attestation employeur ou Kbis, carte grise + macaron rouge) ?\n3. Quelles sont les sanctions prévues par le Code des transports en cas d'exercice illégal de l'activité VTC (article L3124-4) ?\n4. Décrivez la procédure d'inscription au registre national VTC (pièces justificatives, durée de validité, renouvellement quinquennal).\n5. À partir de quels critères le préfet peut-il retirer la carte professionnelle VTC ?\n\nRédigez vos réponses sous forme structurée (3 à 5 lignes par question) en citant les articles de loi pertinents.`,
      `Mise en situation — Gestion d'entreprise VTC\n\nVous lancez votre activité de VTC à compter du 1er du mois prochain. Vous prévoyez un CA mensuel de 4 200€ (160 courses à 26€ en moyenne).\n\n1. Choisissez et justifiez votre statut juridique (micro-entrepreneur, EURL ou SASU). Comparez sur 3 critères : protection patrimoine, charges sociales, comptabilité.\n2. Calculez vos cotisations URSSAF mensuelles (taux 21,2% du CA pour services).\n3. Calculez votre charge fiscale annuelle (versement libératoire 1,7% si option) sur la base de votre CA prévisionnel.\n4. Établissez votre compte de résultat prévisionnel mensuel : CA – cotisations – carburant (450€) – assurance (180€) – véhicule LLD (520€) – autres (200€) = revenu net.\n5. À quel moment devrez-vous basculer en TVA (seuil 36 800€) ? Quelles seront les conséquences ?\n\nProduisez un dossier structuré directement utilisable pour votre démarche d'immatriculation.`,
      `Cas pratique — Développement commercial VTC (épreuve spécifique 2)\n\nVous démarrez votre activité de chauffeur VTC en région parisienne. Votre objectif : atteindre 3 200€ de CA mensuel en 4 mois.\n\n1. Comparez 3 plateformes (Uber, Bolt, Heetch) sur 4 critères : commission, volume de demandes, type de clientèle, paiement.\n2. Élaborez votre stratégie multi-plateformes : sur quelles plateformes vous inscrivez-vous et pourquoi ? Quels créneaux horaires privilégiez-vous sur chacune ?\n3. Définissez votre offre commerciale : véhicule choisi (justifiez), tenue, services additionnels (eau, chargeurs, presse), tarification heures creuses/pleines.\n4. Concevez votre stratégie de fidélisation : carte de visite avec QR code, demande d'avis 5 étoiles, courses régulières (gare/aéroport pour professionnels).\n5. Mettez en place votre suivi : tableau Excel avec date, plateforme, course, montant, frais, marge nette.\n\nLivrable : business plan VTC sur 4 mois avec objectifs chiffrés hebdomadaires.`,
      `Examen blanc — Sécurité routière et secourisme (épreuves communes VTC)\n\nVous êtes en course avec 3 passagers à bord. Sur l'autoroute A6 vers Paris, vous êtes témoin d'un accident impliquant 2 véhicules à 200 mètres devant vous.\n\n1. Décrivez les 3 actions immédiates à mettre en œuvre (Protéger, Alerter, Secourir – PAS).\n2. Comment positionnez-vous votre véhicule pour protéger la zone d'accident sans bloquer les secours ?\n3. Quelles informations transmettez-vous au 112 (numéro européen) ou au 18 (pompiers) ?\n4. Une victime est inconsciente mais respire : décrivez la position latérale de sécurité (PLS) étape par étape.\n5. Vos passagers sont stressés et veulent partir : comment gérez-vous la situation tout en respectant le devoir d'assistance (article 223-6 Code pénal) ?\n\nRédigez un protocole d'intervention détaillé que vous garderez dans votre véhicule professionnel.`,
    ];
    return consignes[(hash + exerciceIdx) % consignes.length];
  }

  // Generic fallback with module-specific content
  const fallbackConsignes = [
    `Dans le cadre du module « ${matiereTitle} », vous êtes placé(e) en situation professionnelle. Votre responsable vous confie la mission suivante :\n\nÀ partir des connaissances acquises en formation (${matiereContenu}), réalisez un travail complet comprenant :\n\n1. Une analyse de la situation proposée en identifiant les enjeux principaux et les parties prenantes.\n2. Un diagnostic structuré utilisant les outils et méthodes vus en cours.\n3. Des propositions d'actions concrètes, chiffrées et planifiées.\n4. Un livrable professionnel directement exploitable (rapport, tableau de bord, procédure, etc.).\n5. Une réflexion sur les points d'amélioration et les compétences mobilisées.\n\nVotre travail sera évalué sur : la pertinence de l'analyse, la qualité de l'argumentation, la structuration du livrable et le lien avec l'expérience en entreprise.`,
    `Exercice pratique – Module « ${matiereTitle} »\n\nContexte : Votre entreprise fait face à un défi opérationnel en lien avec ${matiereContenu}. Votre responsable vous demande de prendre en charge ce dossier.\n\n1. Présentez le contexte et reformulez la problématique avec vos propres mots.\n2. Mobilisez les concepts et outils étudiés en formation pour proposer une méthodologie d'analyse.\n3. Appliquez cette méthodologie à un cas concret issu de votre expérience en entreprise.\n4. Présentez vos résultats sous forme de tableau ou de schéma commenté.\n5. Formulez des recommandations opérationnelles et un plan de mise en œuvre.\n6. Concluez en identifiant les compétences développées et les axes de progression.\n\nLongueur attendue : 2 à 3 pages. Argumentation et exemples concrets obligatoires.`,
  ];
  return fallbackConsignes[(hash + exerciceIdx) % fallbackConsignes.length];
}

/** Module-specific student response builder - returns module-specific text or empty string for fallback */
export function buildModuleSpecificResponse(matiereTitle: string, matiereContenu: string, s: { nom: string; prenom: string; entreprise?: string; poste?: string }, exerciceIdx: number, hash: number): string {
  const mt = (matiereTitle || '').toLowerCase();
  const entreprise = s.entreprise || 'mon entreprise';
  const poste = s.poste || 'mon poste actuel';
  const prenom = s.prenom || 'L\'apprenti';

  // ===== VTC (RS5637) =====
  if (mt.includes('vtc') || mt.includes('réglementation t3p') || mt.includes('t3p') || mt.includes('transport public particulier')) {
    const responses = [
      `Pour cet examen blanc sur la réglementation T3P, j'ai révisé en m'appuyant sur les cours et le site de la CMA.\n\n1. Différences Taxi / VTC :\n- Maraude : seuls les Taxis peuvent prendre un client dans la rue sans réservation. Le VTC doit obligatoirement avoir une réservation préalable.\n- Tarification : les Taxis appliquent un tarif réglementé par arrêté préfectoral (compteur horokilométrique). Les VTC ont une tarification libre fixée à l'avance avec le client.\n- Signalétique : le Taxi a un lumineux sur le toit. Le VTC porte un macaron rouge à l'avant et à l'arrière du véhicule.\n- Retour à la base : après une course, le VTC doit en principe retourner à son lieu d'établissement, sauf nouvelle réservation. Le Taxi peut stationner aux emplacements réservés.\n\n2. Documents obligatoires en cas de contrôle :\n- La carte professionnelle VTC en cours de validité (5 ans).\n- L'attestation d'employeur (si salarié) ou l'extrait Kbis / récépissé d'inscription au registre national VTC (si indépendant).\n- La carte grise du véhicule + l'attestation d'assurance + le macaron rouge apposé sur le véhicule.\n\n3. Sanctions exercice illégal (art. L3124-4 Code des transports) : jusqu'à 1 an d'emprisonnement et 15 000€ d'amende. Confiscation du véhicule possible. Interdiction d'exercer.\n\n4. Procédure d'inscription au registre national VTC : sur le site du ministère des transports, je dois fournir : carte pro VTC, justificatif d'identité, justificatif d'assurance RC pro spécifique VTC, attestation de garantie financière (1 500€). Frais d'inscription : 170€. Validité 5 ans, renouvelable.\n\n5. Retrait de la carte pro par le préfet : condamnation pour des infractions graves (alcool, stupéfiants, délit de fuite), perte des conditions d'honorabilité, défaut d'aptitude physique constaté lors de la visite médicale (obligatoire tous les 5 ans).\n\nMon objectif sur cette épreuve est d'avoir minimum 14/20 pour assurer la note globale.`,
      `Mon projet d'entreprise VTC :\n\n1. Statut juridique – J'ai choisi la micro-entreprise pour démarrer. Comparaison :\n- Patrimoine : la micro ne protège pas mon patrimoine personnel (sauf déclaration insaisissabilité résidence principale, automatique depuis 2015). L'EURL et la SASU oui (responsabilité limitée aux apports).\n- Charges sociales : micro 21,2% du CA (le plus simple). EURL ~45% du bénéfice (TNS). SASU ~80% du salaire (assimilé salarié, mais protection sociale meilleure).\n- Comptabilité : micro = livre des recettes seulement. EURL/SASU = comptabilité complète + bilan annuel + expert-comptable (1 800-2 500€/an).\nDécision : micro pour la simplicité et le coût, je passerai en SASU si je dépasse 60 000€ de CA annuel.\n\n2. Cotisations URSSAF mensuelles : 4 200€ x 21,2% = 890,40€/mois. À déclarer sur le site auto-entrepreneur.fr chaque mois.\n\n3. Charge fiscale (versement libératoire IR 1,7%) : 4 200€ x 1,7% = 71,40€/mois soit 856,80€/an. Avantageuse car mon foyer fiscal me permet d'opter pour ce régime (revenu fiscal référence < 27 478€ part).\n\n4. Compte de résultat prévisionnel mensuel :\n- CA : 4 200€\n- Cotisations URSSAF : -890€\n- Versement libératoire IR : -71€\n- Carburant (essence E10, 11L/100km, 1500km/mois) : -450€\n- Assurance RC pro VTC : -180€\n- LLD véhicule (Peugeot 508) : -520€\n- Autres (lavage, péages, abonnement Waze pro, app de gestion) : -200€\n= Revenu net mensuel : 1 889€\n\n5. Bascule TVA à 36 800€ de CA cumulé. Conséquences : facturer la TVA 20% au client (ou 10% sur les courses transport voyageurs), récupérer la TVA sur achats (carburant 80%, véhicule, etc.), tenue d'une comptabilité TVA. Souvent bénéfique car gros postes déductibles.\n\nCe dossier est prêt pour mon RDV à la CMA pour finaliser mon immatriculation.`,
      `Ma stratégie de développement commercial VTC :\n\n1. Comparaison des 3 plateformes :\n- Uber : commission 25%, énorme volume de demandes (Paris = > 50 000 courses/jour), clientèle mixte (touristes, business, particuliers), paiement hebdomadaire le mardi. Atout : volume. Inconvénient : commission très élevée.\n- Bolt : commission 15-20%, volume en croissance forte, clientèle plutôt jeune et sensible au prix, paiement hebdomadaire. Atout : meilleure marge. Inconvénient : prix course plus bas.\n- Heetch : commission 10%, volume plus faible mais positionnement nightlife (vendredi/samedi 22h-6h), clientèle jeune urbaine, paiement hebdomadaire. Atout : forte marge sur les nuits. Inconvénient : irrégulier.\n\n2. Stratégie multi-plateformes :\n- Lundi-jeudi 6h-10h et 17h-21h : Uber + Bolt en parallèle (forte demande business, courses gare/aéroport).\n- Vendredi-samedi 22h-4h : Heetch en priorité + Uber en backup (clientèle nightlife à forte marge).\n- Dimanche : peu rentable, je travaille 1 dimanche sur 2 sur Uber uniquement (touristes).\nObjectif : 45h de connexion/semaine, 65 courses, panier moyen 28€.\n\n3. Offre commerciale :\n- Véhicule : Peugeot 508 noire (image premium, intérieur cuir, conforme exigences plateformes). LLD 520€/mois pour étaler le coût.\n- Tenue : pantalon noir, chemise blanche, veste. Image professionnelle qui rassure le client.\n- Services additionnels : eau plate (bouteille 50cl), chargeurs Lightning + USB-C, mouchoirs, presse du jour (Le Parisien). Coût total < 30€/mois pour beaucoup d'avis 5 étoiles.\n- Tarification : je ne fixe pas mes tarifs (gérés par plateformes), mais je sais quand les heures de pointe (multiplicateur Uber x1,5 à x2,3) augmentent ma rentabilité.\n\n4. Stratégie de fidélisation :\n- Carte de visite avec QR code vers WhatsApp Business pour réservations directes (sans commission plateforme !).\n- Demande systématique d'avis 5 étoiles à la fin de chaque course agréable (impacte mon ranking et mes courses futures).\n- Identification de clients réguliers (gare-bureau quotidien) à qui je propose une réservation directe par WhatsApp à un tarif fixe attractif.\n\n5. Suivi quotidien sur tableur Google Sheets : date, plateforme, départ-arrivée, montant brut, commission, montant net, km parcourus, durée, note client. Je calcule mon CA jour, marge nette/heure, et j'ajuste ma stratégie chaque dimanche soir.\n\nObjectif validé : 3 200€ de CA mensuel atteignable dès le mois 3.`,
      `Mon protocole d'intervention en cas d'accident sur l'A6 (PAS – Protéger, Alerter, Secourir) :\n\n1. Trois actions immédiates (méthode PAS) :\n- PROTÉGER : ralentir progressivement, allumer les feux de détresse, m'arrêter en sécurité (bande d'arrêt d'urgence à 50m minimum de la zone), enfiler mon gilet jaune (obligatoire) AVANT de sortir, faire enfiler les gilets jaunes à mes 3 passagers.\n- ALERTER : composer le 112 (numéro européen prioritaire) ou le 18 (pompiers). Donner localisation précise (autoroute A6, sens Paris, point kilométrique le plus proche), nombre de véhicules impliqués, présence ou non de blessés, présence éventuelle de fumée/feu.\n- SECOURIR : me protéger d'abord, ne pas déplacer les blessés (sauf danger imminent type incendie), parler aux victimes pour les rassurer en attendant les secours.\n\n2. Position du véhicule : sur la bande d'arrêt d'urgence, à 50m minimum en amont de l'accident, roues braquées vers la droite (pour éviter qu'un choc arrière ne projette le véhicule sur la zone). Je n'utilise PAS le triangle sur autoroute (risque de me faire renverser en l'installant), je laisse les feux de détresse.\n\n3. Informations au 112 : « Bonjour, je suis témoin d'un accident sur l'autoroute A6, sens Lyon-Paris, au PK 17 environ après le péage de Fleury. 2 véhicules sont impliqués. Je vois 1 victime consciente qui marche, 1 victime apparemment inconsciente dans le véhicule. Pas de fumée pour le moment. Je suis sur place avec 3 passagers. Mon nom est ${prenom}, mon numéro 06 XX XX XX XX. Je reste joignable. »\n\n4. Position latérale de sécurité (PLS) – étape par étape :\n- Vérifier que la victime respire (regarder la poitrine + écouter à l'oreille pendant 10 secondes).\n- S'agenouiller sur le côté de la victime, bras de son côté à 90° vers le haut.\n- Plier la jambe opposée et la maintenir.\n- Saisir l'épaule et le genou opposés et tirer vers soi pour faire rouler la victime sur le côté.\n- Stabiliser : main sous la joue, jambe pliée à angle droit pour bloquer la position.\n- Vérifier régulièrement la respiration jusqu'à l'arrivée des secours.\n\n5. Gestion de mes 3 passagers stressés : je leur explique calmement que la loi (article 223-6 du Code pénal) m'oblige à porter assistance à personne en danger sous peine de 5 ans d'emprisonnement et 75 000€ d'amende. Je leur propose de descendre côté glissière (pas côté circulation), de rester groupés derrière la glissière en sécurité. Je leur dis que la course leur sera entièrement remboursée et qu'un autre VTC va être appelé pour finir le trajet. Je documente l'incident pour la plateforme et mon assureur.\n\nCe protocole, je l'ai imprimé et glissé dans la portière conducteur. Mon tuteur en formation m'a dit que les examinateurs aiment les candidats qui ont préparé du concret.`,
    ];
    return responses[(hash + exerciceIdx) % responses.length];
  }

  if (mt.includes('veille commerciale') || (mt.includes('veille') && !mt.includes('information'))) {
    const responses = [
      `Pour réaliser cette veille commerciale, j'ai commencé par identifier les sources d'information les plus pertinantes pour notre secteur d'activité. Chez ${entreprise}, nous travaillons principalement avec des clients B2B, donc j'ai orienté mes recherches en conséquence.\n\nPremièrement, j'ai sélectionné les sources suivantes :\n- LinkedIn Sales Navigator : c'est l'outil que j'utilise quotidienement chez ${entreprise} pour suivre les actualités de nos prospects et concurents. On peut paramétrer des alertes sur les changements de poste, les publications et les recrutements de nos cibles.\n- Le site de la CCI : ils publient des études sectorielles gratuites et des statistiques sur les entreprises de notre région. J'y ai trouvé un rapport sur la croissance du marché des solutions connectées en B2B.\n- Google Alerts : j'ai configuré 5 alertes avec les mots-clés de notre secteur (solution connectée B2B, IoT industriel, capteur professionnel, etc.). Ça me permet de recevoir chaque matin un résumé des articles publiés.\n- Le salon Techinnov à Paris : c'est LE salon de référence pour notre secteur. Mon responsable commercial y va chaque année et il m'a dit que c'est là qu'on voit les nouvelles tendances avant tout le monde.\n- La newsletter Maddyness : elle couvre l'actualité de l'innovation et des startups tech. Même si c'est pas directement notre secteur, ça permet de voir les innovations qui pourrait nous concerner à moyen terme.\n\nPour l'analyse concurentielle, j'ai étudié 3 acteurs :\n\nConcurrent 1 – TechSmart : Leader du marché avec 35% de parts de marché. Forces : marque reconnue, large gamme, SAV réactif. Faiblesses : prix élevés, peu d'innovation récente, relation client impersonnele.\n\nConcurrent 2 – ConnectPro : Challenger agressif en croissance de 25% par an. Forces : prix compétitifs, innovation produit, présence web forte. Faiblesses : SAV sous-dimensionné, peu de références grands comptes, fiabilité discutée.\n\nConcurrent 3 – SmartLink : Acteur de niche spécialisé haut de gamme. Forces : qualité premium, expertise technique, clients fidèles. Faiblesses : gamme limitée, prix très élevés, peu de visibilité commerciale.\n\nConcernant les tendances du marché, j'ai identifié plusieurs éléments importants : la croissance du marché de l'IoT industriel est estimé à +18% par an selon l'étude Xerfi 2024. La réglementation européenne sur la cybersécurité des objets connectés va entrer en vigueur et imposer de nouvelles normes. Aussi, la demande pour des solutions avec IA intégrée explose.\n\nPour le tableau de bord de veille, je propose de suivre mensuellement : nombre de nouveaux articles détectés, mouvements des concurrents, évolution des prix du marché, nouvelles réglementations, et tendances Google Trends sur nos mots-clés.`,
      `J'ai commencé cet exercice en me basant sur ce qu'on a vu en formation sur les outils de veille et l'analyse concurentielle.\n\nPour les sources de veille, voici mes 5 choix :\n1. Societe.com et Pappers : pour surveiller les infos financières et juridiques de nos concurents. Chez ${entreprise}, mon responsable m'a montré comment vérifier la santé financière d'un prospect avant de le démarcher.\n2. Les réseaux sociaux profesionnels (LinkedIn, Twitter/X) : pour suivre les publications de nos concurrents et les tendances du secteur.\n3. Les salons professionnels et webinaires : comme le salon Solutions à Paris.\n4. La presse spécialisée en ligne : UsineDigitale, JDN ou 01net pour les actualités tech.\n5. Les rapports d'études de marché : Xerfi, INSEE, Bpifrance publient des analyses sectorielles très complètes.\n\nJ'ai ensuite fait la matrice SWOT de 3 concurrents. La matrice montre que notre principal avantage compétitif c'est notre proximité client et notre réactivité. Par contre, on est plus petit que les autres donc on a moins de moyen pour la communication.\n\nPour les tendances, je retiens : le marché se digitalise, les clients veulent tout en ligne. La réglementation évolue avec les nouvelles normes environnementales. L'IA commence à être utilisée pour la prédiction commerciale.\n\nMon tableau de bord mensuel comprendrait : récapitulatif des mouvements concurrentiels, nouvelles réglementations, tendances marché, opportunités détectées, et un score de menace de 1 à 5.`,
    ];
    return responses[(hash + exerciceIdx) % responses.length];
  }

  if (mt.includes('prospecter') || mt.includes('prospection')) {
    return `Pour constituer mon fichier de prospection, j'ai utilisé les critères de segmentation qu'on a vu en cours. Mon objectif est d'obtenir 12 RDV qualifiés en 4 semaines.\n\nCritères de sélection :\n- Secteur : industrie manufacturière, métallurgie, plasturgie, agroalimentaire\n- Taille : 20 à 250 salariés\n- CA : entre 2M€ et 25M€\n- Localisation : rayon de 80km autour de notre agence\n- Pas déjà client chez nous ou chez notre concurrent principal\n\nJ'ai utilisé LinkedIn Sales Navigator et Societe.com pour constituer ma liste. Chez ${entreprise}, on a accès à ces outils.\n\nScript de phoning :\n« Bonjour, ${prenom} de ${entreprise}, je me permet de vous appeler car nous accompagnons des entreprises comme la vôtre dans [besoin spécifique]. Êtes-vous la personne en charge de [domaine] ? »\n\n[Si oui] « Parfait, je vais être bref. Nous avons récemment aidé [référence] à [résultat concret]. Je souhaiterais vous présenter comment nous pourrions faire de même. Seriez-vous disponible pour un échange de 20 minutes la semaine prochaine ? »\n\nTraitement des objections :\n\n« On travaille déjà avec un fournisseur » → « Je comprends tout à fait. Beaucoup de nos clients travaillaient aussi avec d'autres prestataires. L'idée c'est simplement de vous montrer une approche complémentaire. 20 minutes, sans engagement, qu'en pensez-vous ? »\n\n« Envoyez-moi une documentation » → « Bien sûr. Cela dit, nos solutions sont spécifiques et un échange de quelques minutes me permettrait de vous envoyer exactement ce qui correspond à vos besoins. Quand seriez-vous disponible ? »\n\n« Pas de budget en ce moment » → « Je comprends. Justement, si on se rencontre maintenant, ça vous permettra de préparer votre budget avec toutes les informations. »\n\nEmail de prospection :\nObjet : [Nom entreprise] – Optimisez votre [processus] comme [référence]\nCorps : Introduction personnalisée + 1 bénéfice chiffré + call to action\n\nEmail de relance J+5 :\nObjet : Suite à mon message – [bénéfice clé]\nCorps : Rappel bref + nouvel élément + proposition de créneau\n\nMessage LinkedIn :\n« Bonjour [Prénom], j'ai vu que [élément personnalisé]. Chez ${entreprise}, nous aidons les [type d'entreprise] à [bénéfice]. Je serais ravi d'échanger avec vous. Bonne journée ! »\n\nPlanning sur 4 semaines :\n- Lundi matin : préparation des appels\n- Mardi et mercredi : sessions de phoning (9h30-12h et 14h-17h)\n- Jeudi matin : envoi des emails et relances LinkedIn\n- Jeudi après-midi : RDV physiques\n- Vendredi : suivi CRM, bilan de la semaine\n\nObjectif quotidien : 25 appels, 3 contacts argumentés, 1 RDV décroché.`;
  }

  if (mt.includes('plan d\'actions') || mt.includes('plan d\'action')) {
    return `Pour ce plan d'actions commerciales, j'ai suivi la méthodologie SMART vue en cours.\n\nMes 4 objectifs SMART :\n1. Augmenter le CA de 380 000€ à 520 000€ d'ici le 31/12/N+1, soit +37%\n2. Acquérir 15 nouveaux clients sur la zone d'ici 6 mois\n3. Atteindre un taux de transformation des devis de 30% à fin juin\n4. Réaliser 20 visites de prospection par mois minimum\n\nPlan d'actions sur 6 mois :\n\nMois 1-2 – Phase de lancement :\n- Constitution du fichier de prospection (200 cibles qualifiées)\n- Campagne emailing d'introduction : 3 séquences de 4 emails\n- Social selling LinkedIn : 10 connexions qualifiées/jour\n- Budget : 1 200€\n\nMois 3-4 – Phase d'accélération :\n- Prospection terrain intensive : 5 RDV/semaine\n- Participation salon régional\n- Webinaire client\n- Budget : 4 500€\n\nMois 5-6 – Phase de consolidation :\n- Relance systématique des prospects chauds et tièdes\n- Événement client VIP\n- Analyse des résultats et ajustements\n- Budget : 1 800€\n\nBudget total : 7 500€\n\nTableau de bord CRM :\n- Nombre de RDV : objectif 20/mois (hebdomadaire)\n- Devis envoyés : objectif 12/mois\n- Taux de transformation : 30%\n- CA signé : 86 667€/mois\n- Pipe commercial : >250 000€\n\nPlan B si résultats < 80% à mi-parcours :\n- Renforcer la prospection téléphonique\n- Offres promotionnelles de lancement\n- Demander des recommandations aux clients existants\n- RDV en binôme avec le directeur commercial\n\nChez ${entreprise}, j'ai déjà commencé à appliquer certaines méthodes. Mon tuteur m'a montré comment utiliser le CRM et je me rend compte que sans ce suivi, on perd beaucoup d'opportunités.`;
  }

  if (mt.includes('performance') || mt.includes('analyser ses performances')) {
    return `J'ai analysé les résultats du T3 en reprenant les méthodes d'analyse des écarts qu'on a étudié en formation.\n\nAnalyse des écarts :\n- CA : 187 000€ vs 250 000€ → écart de -63 000€ soit -25,2%. C'est significatif.\n- RDV : 52 réalisés sur 80 planifiés → taux de réalisation de 65%. Il y a eu beaucoup d'annulations.\n- Taux de transformation : 15/52 = 28,8% sur RDV réalisés. Ah non pardon, c'est 15 commandes sur 80 RDV prévus = 18,75%. C'est en dessous.\n- Panier moyen : 12 467€ vs 15 000€ → écart de -16,9%\n\nPoints forts :\n- Le taux de transformation sur RDV réalisés est pas mal (28,8%)\n- On a quand même fait 75% de l'objectif CA\n\nPoints faibles :\n- Trop d'annulations de RDV (35%!)\n- Panier moyen en baisse\n- Peu de prospection grands comptes\n\nHypothèses sur les causes :\n1. Annulations : période estivale + prospects pas assez qualifiés\n2. Panier moyen faible : on accepte les petites commandes. Mon tuteur m'a dit qu'il faut mieux qualifier.\n3. Clients perdus : 2 sur 3 pour le prix, 1 pour les délais\n\nPlan d'actions T4 :\n- Scoring prospect avant RDV (budget, projet, décideur). Si score < 6/10, pas de déplacement.\n- Cibler 10 grands comptes > 20 000€\n- Contacter les 3 clients perdus\n- Packages avec services complémentaires pour augmenter le panier moyen\n\nNouveaux objectifs T4 :\n- CA : 200 000€ (+7% vs T3)\n- RDV : 60 avec taux de réalisation > 80%\n- Panier moyen : 14 000€\n- Taux de transformation : 30%\n\nJe sais que ses objectifs sont ambitieux mais c'est atteignable avec les actions correctives.`;
  }

  if (mt.includes('représenter') || mt.includes('valoriser')) {
    return `Pour préparer ma participation au salon, j'ai travaillé sur plusieurs éléments.\n\nMon elevator pitch de 90 secondes :\n« Bonjour, je suis ${prenom} de ${entreprise}. Nous sommes spécialisés dans [domaine] depuis [X] ans. Ce qui nous différencie ? Notre approche personnalisée : 95% de nos clients renouvellent leur confiance. Nous accompagnons plus de 200 entreprises. Concrètement, notre dernier client a [résultat chiffré]. Je serais ravi de vous montrer comment nous pourrions faire de même. Puis-je vous poser quelques questions ? »\n\nJ'ai chronométré et ça fait 85 secondes. Mon tuteur m'a fait remarquer qu'il faut pas parler trop vite sinon ça fait agressif.\n\nArgumentaire de valorisation :\n- Historique : « Créée en [année], ${entreprise} bénéficie de [X] ans d'expertise »\n- Certifications : « Nous sommes certifiés, gage de notre engagement qualité »\n- Références : « Nous comptons parmis nos clients [3 références notoires] »\n- Valeurs : « Proximité, expertise technique et réactivité »\n- Chiffres clés : « X collaborateurs, X clients actifs, taux de satisfaction de X% »\n\nMes 5 questions d'accroche :\n1. « Quel est votre principal défi cette année en matière de [sujet] ? »\n2. « Comment gérez-vous actuellement [processus] ? »\n3. « Avez-vous déjà envisagé de [solution] ? »\n4. « Qu'est-ce qui vous a amené sur le salon ? Vous cherchez quelque chose en particulier ? »\n5. « Travaillez-vous déjà avec un prestataire ? Qu'est-ce qui vous satisfait ou frustre ? »\n\nCes questions sont ouvertes exprès. En formation, on a appris que le meilleur commercial est celui qui écoute plus qu'il parle.\n\nPlan de suivi post-salon :\n- J+1 : Saisie de tous les contacts dans le CRM\n- J+2 : Email personnalisé de remerciement\n- J+3 à J+7 : Appel aux contacts chauds\n- J+7 à J+14 : Relance email aux contacts tièdes\n- J+30 : 2ème relance pour les sans réponse\n\nCompte-rendu type : formulaire avec nom/prénom/entreprise/fonction, besoin exprimé, budget estimé, calendrier, prochain pas, niveau d'intérêt (1 à 5).`;
  }

  if (mt.includes('proposition technique') || mt.includes('concevoir une proposition')) {
    return `J'ai travaillé sur la proposition technique pour le client. C'est un exercice intéressant parce que chez ${entreprise}, j'ai assisté à une proposition similaire le mois dernier.\n\nAnalyse des besoins reformulés :\n1. Gestion des stocks temps réel : le client perd 15% de productivité à cause de ruptures non anticipées. Ils utilisent un Excel souvent pas à jour.\n2. Suivi de production avec traçabilité : obligation réglementaire, actuellement fait sur papier.\n3. Facturation : 2 salariés à temps plein sur la saisie, gros potentiel d'automatisation.\n4. Accès mobile : les 8 commerciaux terrain n'ont aucun accès au stock et aux prix.\n\nOption A (Standard) :\n- ERP SaaS, modules : Stock, Production, Facturation, CRM Mobile\n- Hébergement cloud sécurisé\n- 35 licences\n- Formation : 3 jours + 2 sessions de suivi\n\nChiffrage Option A :\n- Licences : 35 x 89€/mois = 37 380€/an\n- Installation : 4 500€\n- Migration : 2 800€\n- Formation : 3 500€\n- Total année 1 : 48 180€\n\nOption B (Premium) :\n- Même base + BI et maintenance prédictive\n- Interface personnalisée\n- Support 24/7\n\nChiffrage Option B :\n- Licences : 35 x 119€/mois = 49 980€/an\n- Installation + personnalisation : 8 500€\n- Migration : 3 200€\n- Formation : 6 400€\n- Total année 1 : 68 080€\n\nROI :\n- Réduction ruptures stock : 45 000€/an\n- Automatisation facturation : 52 000€/an\n- Réduction erreurs traçabilité : 12 000€/an\n- ROI : Option A = 9 mois | Option B = 14 mois\n\nPlanning déploiement : audit (S1-2), migration (S3-4), formation clés (S5), mise en prod (S6), autres users (S7-8)\n\nObjéctions anticipées :\n1. « Plus cher que prévu » → ROI à 9 mois\n2. « Résistance au changement » → Accompagnement inclus\n3. « Si ça marche pas ? » → Test 30 jours`;
  }

  if (mt.includes('négocier') || mt.includes('négociation')) {
    return `Cet exercice de négociation est très formateur. J'ai préparé ma strategie avec la méthode CRAC vue en formation.\n\nStratégie de négociation :\n\nConcessions possibles :\n- Période d'essai : OK pour 3 mois (pas 6) avec engagement ferme ensuite\n- Clause de sortie : préavis de 6 mois\n- Remise de 5% sur le volume si engagement 3 ans\n- Formation offerte\n\nLignes rouges :\n- Pas de baisse > 8% (marge minimum 25%)\n- Délai d'intervention : 3h possible mais pas 2h\n- Pas de période d'essai sans engagement\n\nTraitement des objections (méthode CRAC) :\n\n« Prix 15% plus élevé » :\nC = Creuser : « Pouvez-vous préciser ce qui est inclus dans l'offre concurrente ? »\nR = Reformuler : « À première vue notre offre semble plus chère »\nA = Argumenter : « Notre offre inclut astreinte 24/7, pièces détachées, reporting mensuel. À périmètre égal, l'écart réel est < 5%. Notre taux de disponibilité garanti à 99,5% évite des arrêts coûteux (estimé 25 000€/incident). »\nC = Conclure : « En tenant compte de ces éléments, notre proposition est-elle cohérente ? »\n\n« Période d'essai de 6 mois » :\nC : « Qu'est-ce qui motive cette durée ? »\nR : « Vous voulez vous assurer de la qualité »\nA : « 3 mois suffisent pour évaluer. Si les résultat ne sont pas au RDV, on prolonge gratuitement. »\nC : « Cette proposition vous semble raisonable ? »\n\n« Clause de sortie à tout moment » :\nC : « Qu'est-ce qui vous inquiète ? »\nR : « Vous voulez pouvoir vous désengager si insatisfait »\nA : « Engagement annuel avec préavis 3 mois. Nos SLA sont contractuels : si non respectés, résiliation sans pénalité. »\n\nContre-offre :\n- Prix : 72 000€/an (-7,7%) → marge 26%\n- Engagement : 3 ans avec révision annuelle\n- Essai : 3 mois avec KPIs\n- Intervention : 3h garanti\n- Bonus : formation + reporting mensuel\n\nMon tuteur chez ${entreprise} m'a dit que dans une négociation, il faut toujours avoir quelque chose à donner. Je trouve que c'est un conseil très pertinant.`;
  }

  if (mt.includes('relation client') || mt.includes('fidélisation') || mt.includes('gestion de la relation')) {
    return `La fidélisation c'est un sujet que je vis au quotidien chez ${entreprise} en tant que ${poste}.\n\nSegmentation du portefeuille (75 clients) :\n\nClients A (15 clients, 20%) : CA > 15 000€/an → Contact mensuel, RDV trimestriel, événements VIP\nClients B (25 clients, 33%) : CA 5 000-15 000€ → Contact bimestriel, newsletter personnalisée\nClients C (35 clients, 47%) : CA < 5 000€ → Contact trimestriel, communication automatisée\n\nPlan de fidélisation Segment A :\n- Interlocuteur dédié\n- 2 événements VIP/an\n- Remise volume progressive (3%, 5%, 8%)\n- Bilan annuel formalisé\n- Accès prioritaire aux nouveautés\n\nSegment B :\n- Email mensuel personnalisé (pas que commercial!)\n- Offre parrainage : -5% pour eux et le filleul\n- Questionnaire satisfaction semestriel\n- Cross-selling proactif\n\nSegment C :\n- Newsletter trimestrielle automatisée\n- Offres promotionnelles saisonnières\n- Réactivation clients inactifs > 6 mois\n\nProcessus de gestion des réclamations en 5 étapes :\n1. RÉCEPTION : Accuser réception dans les 2h. Créer un ticket CRM.\n2. ANALYSE : Investiguer dans les 24h.\n3. RÉPONSE : Solution concrète dans les 48h. Appel téléphonique obligatoire.\n4. RÉSOLUTION : Mise en œuvre. Vérification avec le client.\n5. SUIVI : Recontacter à J+15. Analyse cause racine.\n\nQuestionnaire satisfaction (10 questions) :\n1. Recommanderiez-vous notre entreprise ? (NPS)\n2. Qualité des produits/services ?\n3. Réactivité de l'interlocuteur ?\n4. Délais de livraison ?\n5. Rapport qualité/prix ?\n6. SAV ?\n7. Informations utiles ?\n8. Problème rencontré ?\n9. Aspects à améliorer ?\n10. Besoins non couverts ?\n\nAlertes CRM :\n- Rouge : sans commande > 90 jours → appel immédiat\n- Orange : baisse CA > 20% sur 3 mois → RDV\n- Jaune : réclamation non résolue > 48h → escalade\n- Verte : anniversaire contrat → remerciement + offre\n\nChez ${entreprise}, on fait déjà certaines choses mais pas de manière aussi structuré. Mon tuteur m'a dit que la clé c'est la régularité.`;
  }

  if (mt.includes('bilan') || mt.includes('ajuster')) {
    return `Pour ce bilan d'activité annuel, j'ai repris la méthode vue en formation.\n\nContexte : L'année a été marqué par une conjoncture économique tendue avec une concurrence accrue sur notre secteur. Malgré ça, l'équipe a su maintenir un niveau d'activité correct.\n\nRésultats vs Objectifs :\n- CA : 425 000€ / 480 000€ → 88,5% (écart -55 000€)\n- Nouveaux clients : 18 / 25 → 72%\n- Transformation devis : 32% / 40% → en dessous\n- Satisfaction : 4,2/5 → bon niveau\n- Clients perdus : 2 (CA perdu 35 000€)\n- Marge : 31% → conforme\n\n3 facteurs de succès :\n1. La satisfaction client reste élevée (4,2/5), ce qui assure une bonne fidélisation\n2. La marge est maintenue à 31%, on n'a pas sacrifié la rentabilité pour faire du volume\n3. Les 18 nouveaux clients montrent que la prospection fonctionne, même si on est en dessous de l'objectif\n\n3 principaux freins :\n1. Le taux de transformation des devis est trop faible (32% vs 40%). On perd trop de deals. Hypothèse : nos devis arrivent trop tard ou ne sont pas assez personnalisés.\n2. L'acquisition de nouveaux clients est insuffisante (18 vs 25). On a pas assez prospecté, surtout au S1.\n3. La perte de 2 clients representant 35 000€ de CA. Les deux sont partis pour des raisons de prix.\n\nRecommandations N+1 :\n- Accélérer le délai de production des devis (objectif : 48h max vs 5 jours aujourd'hui)\n- Mettre en place un process de relance systématique des devis non signés à J+3, J+7, J+14\n- Intensifier la prospection dès janvier (pas attendre mars comme cette année)\n- Programme de fidélisation formalisé pour les clients A\n\nObjectifs N+1 :\n- CA : 500 000€ (+17,6% vs réalisé, +4,2% vs objectif N)\n- 22 nouveaux clients\n- Taux transformation : 38%\n- 0 client perdu\n\nPlan trimestriel : T1 = prospection intensive, T2 = conversion, T3 = consolidation, T4 = fidélisation et préparation N+2\n\nJe pense que ses objectifs sont réalistes si on met en place les actions dès le début de l'année.`;
  }

  // Assistant de direction responses
  if (mt.includes('organiser et coordonner') || mt.includes('gestion d\'agenda') || mt.includes('organisation')) {
    return `Pour organiser le séminaire annuel, j'ai procédé méthodiquement en suivant les étapes vues en cours.\n\nComparatif des 3 lieux :\n\n1. Domaine des Oliviers (Montpellier) : Capacité 50 pers, salles modulables, piscine, restaurant gastronomique. Prix : 4 200€ les 2 jours (hébèrgement + repas). Accessibilité : 15min de l'autoroute, parking 40 places. + : cadre exceptionel. - : un peu loin du centre-ville.\n\n2. Hôtel Mercure Centre (Montpellier) : Capacité 60 pers, 3 salles de réunion, équipement audiovisuel inclus. Prix : 3 800€. Accessibilité : centre-ville, tram, parking payant. + : pratique et bien équipé. - : cadre classique.\n\n3. Château de la Formation (Nîmes) : Capacité 40 pers, parc de 3 hectares, activités outdoor. Prix : 5 100€. Accessibilité : 30min de Montpellier. + : cadre unique pour team-building. - : budget dépassé, capacité juste.\n\nMa recommandation : Option 1 – Domaine des Oliviers. Meilleur rapport qualité/prix/capacité.\n\nProgramme détaillé :\n\nJour 1 :\n9h00 – Accueil café\n9h30 – Plénière d'ouverture par le Directeur\n10h30 – Pause\n10h45 – Atelier 1 : Bilan de l'année (3 groupes)\n12h30 – Déjeuner\n14h00 – Atelier 2 : Objectifs N+1\n15h30 – Pause\n15h45 – Atelier 3 : Innovation et projets\n17h30 – Synthèse plénière\n19h00 – Apéritif + Dîner\n\nJour 2 :\n9h00 – Team-building (activité outdoor)\n12h00 – Déjeuner\n14h00 – Tables rondes thématiques\n16h00 – Clôture et engagement collectif\n\nRétroplanning :\nJ-60 : Réserver le lieu, envoyer save the date\nJ-45 : Programme définitif, réserver prestataires\nJ-30 : Envoyer invitations officielles\nJ-15 : Relance + liste des participants\nJ-7 : Vérifier logistique, préparer supports\nJ-1 : Check final sur place\nJ+7 : Envoi du CR et des photos\n\nBudget prévisionnel :\n- Lieu + hébergement + repas : 4 200€\n- Team-building : 1 500€\n- Matériel et impression : 500€\n- Transport : 800€\n- Marge de sécurité : 1 000€\n- TOTAL : 8 000€ (dans le budget de 12 000€, il reste 4 000€ de marge)\n\nJ'ai fait relire ce programme à mon tuteur qui m'a suggéré d'ajouter un ice-breaker le matin du jour 1 pour détendre l'atmosphère. Bonne idée.`;
  }

  if (mt.includes('communication écrite') || mt.includes('anglais') || mt.includes('rédaction') || mt.includes('correspondance')) {
    return `Exercice 1 – Compte-rendu de réunion :\n\nCOMPTE-RENDU DE RÉUNION DE DIRECTION\nDate : [date]\nPrésents : M. le Directeur, Mme la DRH, M. le DAF, Mme la DC\n\nOrdre du jour :\n1. Lancement nouveau produit\n2. Budget Q3\n3. Recrutements\n\n1. LANCEMENT PRODUIT\nLe lancement du nouveau produit est prévu le 15 octobre. La campagne de comunication sera lancée 3 semaines avant. Le plan média est en cours de finalisation. Point d'attention : vérification juridique en cours sur le packaging.\n\n2. BUDGET Q3\nLe budget de 85 000€ a été validé à l'unanimité. La prévision de CA est en hausse de +12% par rapport au Q2. Le DAF souligne la nécessité de maîtriser les coûts fixes.\n\n3. RECRUTEMENTS\nDeux recrutements en CDI sont prévus : un commercial terrain et un chargé de communication digitale. Les annonces seront publiées d'ici fin de semaine.\n\nProchaine réunion : [date], 9h00.\n\nExercice 2 – Traduction anglais :\n\nKey decisions from the management meeting:\n- New product launch: scheduled for October 15th, with a 3-week pre-launch campaign\n- Q3 budget: €85,000 approved, +12% revenue forecast\n- Recruitment: 2 permanent positions planned (sales rep and digital comm manager)\n\nExercice 3 – Email fournisseur :\n\nSubject: Payment Terms – Request for Extension\n\nDear Mr. Johnson,\n\nI hope this email finds you well. Following our recent discussions, I am writing to request an adjustment to our current payment terms.\n\nAs you know, our partnership has been growing steadily over the past two years, with increasing order volumes. In order to support this growth and maintain our cash flow management, we would like to propose extending our payment terms from 30 to 60 days.\n\nThis adjustment would allow us to continue increasing our orders while maintaining a healthy business relationship. We remain fully commited to our partnership and look forward to discussing this proposal at your earliest convenience.\n\nBest regards,\n${prenom}\n\nExercice 4 – Note interne :\n\nNOTE INTERNE\nObjet : Réorganisation – Fusion des services Marketing et Communication\n\nChers collaborateurs,\n\nNous avons le plaisir de vous informer que, dans le cadre de notre stratégie de développement, les services Marketing et Communication seront fusionnés à compter du 1er mars.\n\nCette réorganisation vise à renforcer la cohérence de nos actions et à optimiser nos ressources. M. [Nom] assurera la direction du nouveau pôle « Marketing & Communication ».\n\nUne réunion d'information sera organisée le [date] pour répondre à vos questions.\n\nExercice 5 – Correction du courrier :\n\nVersion corrigée :\n« Monsieur,\n\nSuite à notre conversation téléphonique, je vous transmets les documents demandés.\n\nJe vous serais reconnaissante de bien vouloir les signer et de nous les retourner dans les meilleurs délais.\n\nJe reste à votre disposition pour tout renseignement complémentaire.\n\nCordialement, »\n\nErreurs corrigées : « a » → « à » (accent), « envoi » → « transmets » (conjugaison + registre), « demander » → « demandés » (accord participe passé), « bref delais » → « meilleurs délais » (expression figée + pluriel). J'ai aussi ajouté une formule de politesse qui manquait complètement.`;
  }

  // No specific match - return empty string for fallback to generic builder
  return '';
}
